                 plot::PsdConfig cfg;
                 cfg.sampleRate = Fs;
                 cfg.nfft = nfft > 0 ? uint32_t(nfft) : 0;
                 cfg.noverlap = noverlap > 0 ? uint32_t(noverlap) : 0;
